if(span){const m=/^\s*(\d+)\s*\/\s*(\d+)\s*$/.exec(span.textContent||"");if(m){const a=Number(m[1]),b=Number(m[2]);if(b>0){frac=Math.max(0,Math.min(1,a/b));label=a+" / "+b}}}
const pct=null==frac?null:Math.round(frac*100);
